// Section header
export function SectionHead({
  emoji,
  title,
  titleAr,
  sub,
  subAr,
  color = DS.cyan,
  action,
}: {
  emoji: ReactNode;
  title: string;
  titleAr?: string;
  sub?: string;
  subAr?: string;
  color?: string;
  action?: { label: string; labelAr?: string; onClick: () => void };
}) {
  const { language } = useLanguage();
  const ar = language === 'ar';
  const displayTitle = ar && titleAr ? titleAr : title;
  const displaySub = ar && subAr ? subAr : sub;

  return (
    <div
      className="sp-head"
      style={{
        background: GRAD_HERO,
        borderRadius: R.xxl,
        padding: '26px 24px',
        marginBottom: 20,
        position: 'relative',
        overflow: 'hidden',
        border: `1px solid ${color}20`,
        boxShadow: SH.lg,
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: 0,
          background: `linear-gradient(120deg, ${color}12, transparent 36%, ${'var(--secondary)'})`,
          pointerEvents: 'none',
        }}
      />
      <div
        className="sp-head-inner"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          position: 'relative',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <div
            style={{
              width: 58,
              height: 58,
              borderRadius: R.xl,
              background: `${color}18`,
              border: `1.5px solid ${color}34`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color,
              flexShrink: 0,
            }}
          >
            {emoji}
          </div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4 }}>
              <h1
                style={{
                  fontSize: '1.62rem',
                  fontWeight: 950,
                  color: 'var(--foreground)',
                  margin: 0,
                  letterSpacing: 0,
                }}
              >
                {displayTitle}
              </h1>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 }}>
              {displaySub && (
                <span style={{ color: 'var(--muted-foreground)', fontSize: '0.78rem' }}>{displaySub}</span>
              )}
            </div>
          </div>
        </div>
        {action && (
          <button
            onClick={action.onClick}
            className="sp-head-btn"
            style={{
              height: 44,
              padding: '0 22px',
              borderRadius: R.full,
              border: 'none',
              background: GRAD,
              color: 'var(--background)',
              fontWeight: 900,
              fontSize: '0.875rem',
              boxShadow: SH.blueL,
              cursor: 'pointer',
              flexShrink: 0,
            }}
          >
            {ar && action.labelAr ? action.labelAr : action.label}
          </button>
        )}
      </div>
    </div>
  );
}

